{
  "name": "scopesignal",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Fixture-first acceptance checkpoints and auditable Sandbox milestone payments",
  "scripts": {
    "test": "node --test",
    "serve": "node scripts/serve.mjs"
  },
  "engines": { "node": ">=24" }
}

import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
const root = process.cwd();
const types = { '.html': 'text/html; charset=utf-8', '.mjs': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };
createServer(async (req, res) => {
  try {
    const pathname = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
    const safe = normalize(pathname).replace(/^([.][.][/\\])+/, '').replace(/^[/\\]+/, '');
    const path = join(root, safe || 'index.html');
    const body = await readFile(path);
    res.writeHead(200, { 'content-type': types[extname(path)] || 'application/octet-stream', 'cache-control': 'no-store' }); res.end(body);
  } catch { res.writeHead(404); res.end('Not found'); }
}).listen(Number(process.env.PORT || 4173), '127.0.0.1', () => console.log(`ScopeSignal at http://127.0.0.1:${process.env.PORT || 4173}`));

export const SPEC_VERSION = 1;

export const FIXTURE = Object.freeze({
  id: 'fixture-signal-studio',
  label: 'Northstar onboarding refresh',
  currency: 'USD',
  amount: 120000,
  buyer: 'Northstar Studio (fictional fixture)',
  seller: 'Signal Works (fictional fixture)',
  brief: 'Refresh the onboarding flow for a small-business invoicing app. Deliver an accessible first-run checklist, responsive billing setup, and a documented handoff.',
  checkpoints: [
    { id: 'journey', title: 'First-run checklist', amount: 40000, evidence: 'A screen recording shows the checklist completion path and reset behavior.' },
    { id: 'accessibility', title: 'Accessible billing setup', amount: 40000, evidence: 'Keyboard-only walkthrough and automated accessibility report for the billing setup.' },
    { id: 'handoff', title: 'Responsive handoff', amount: 40000, evidence: 'Desktop and mobile handoff files plus implementation notes.' }
  ]
});

const EVENT_FIELDS = Object.freeze({
  'checkpoint.approved': ['checkpointId', 'approver', 'acceptedEvidence'],
  'paypal.order.created': ['checkpointId', 'orderId', 'amount', 'currency', 'environment'],
  'paypal.capture.requested': ['checkpointId', 'orderId', 'environment'],
  'paypal.capture.response_lost': ['checkpointId', 'orderId', 'outcome'],
  'paypal.webhook.received': ['checkpointId', 'eventId', 'captureId', 'duplicate', 'amount', 'currency'],
  'paypal.capture.reconciled': ['checkpointId', 'captureId', 'outcome', 'source'],
});

function requireId(value, label) {
  if (typeof value !== 'string' || !value || value.trim() !== value) {
    throw new Error(`${label} must be a nonempty string without surrounding whitespace`);
  }
}

function requireCents(value, label) {
  if (!Number.isSafeInteger(value) || value < 0) throw new Error(`${label} must be nonnegative safe integer cents`);
}

const fixtureOrderId = checkpointId => `SANDBOX-${checkpointId.toUpperCase()}`;

function copySeed(seed) {
  const copy = structuredClone(seed);
  if (!copy || !Array.isArray(copy.checkpoints)) throw new Error('Checkpoint seed is required');
  requireId(copy.currency, 'Currency');
  requireCents(copy.amount, 'Project cap');
  const ids = new Set();
  const orderIds = new Set();
  let total = 0;
  for (const cp of copy.checkpoints) {
    requireId(cp?.id, 'Checkpoint ID');
    if (ids.has(cp.id)) throw new Error('Checkpoint IDs must be unique');
    ids.add(cp.id);
    const orderId = fixtureOrderId(cp.id);
    if (orderIds.has(orderId)) throw new Error('Checkpoint IDs must produce unique fixture order IDs');
    orderIds.add(orderId);
    requireCents(cp.amount, 'Checkpoint amount');
    total += cp.amount;
    requireCents(total, 'Checkpoint total');
  }
  if (total > copy.amount) throw new Error('Checkpoint total exceeds the project cap');
  return copy;
}

function checkpoint(checkpoints, id) {
  if (typeof id !== 'string' || !Object.hasOwn(checkpoints, id)) throw new Error('Unknown checkpoint');
  return checkpoints[id];
}

function validateEnvelope(event) {
  if (!event || typeof event !== 'object' || Array.isArray(event) || typeof event.type !== 'string' || !Object.hasOwn(EVENT_FIELDS, event.type)) {
    throw new Error('Unsupported ledger event');
  }
  const allowed = ['seq', 'type', 'at', ...EVENT_FIELDS[event.type]];
  if (Object.keys(event).some(key => !allowed.includes(key))) throw new Error('Unsupported ledger event field');
  if (Object.hasOwn(event, 'seq') && (!Number.isSafeInteger(event.seq) || event.seq < 1)) throw new Error('Invalid event sequence');
  if (Object.hasOwn(event, 'at')) requireId(event.at, 'Event time');
}

function requireOrder(event, cp) {
  requireId(event.orderId, 'Order ID');
  if (event.orderId !== cp.orderId) throw new Error('Order identity conflict');
}

function requireAmount(event, cp, currency) {
  if (event.amount !== cp.amount || event.currency !== currency) throw new Error('Order amount or currency conflict');
}

export function createLedger(seed = FIXTURE) {
  const initialSeed = copySeed(seed);
  const events = [];
  const append = (type, data = {}) => {
    if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error('Event data must be an object');
    const descriptors = Object.getOwnPropertyDescriptors(data);
    if (Object.values(descriptors).some(descriptor => !Object.hasOwn(descriptor, 'value'))) throw new Error('Event data must not contain accessors');
    if (['seq', 'type', 'at'].some(key => Object.hasOwn(descriptors, key))) throw new Error('Reserved event metadata');
    const payload = Object.fromEntries(Object.entries(descriptors).filter(([, descriptor]) => descriptor.enumerable).map(([key, descriptor]) => [key, descriptor.value]));
    const event = Object.freeze({ seq: events.length + 1, type, at: `T+${String(events.length + 1).padStart(3, '0')}`, ...payload });
    // Admission and replay use the same state machine. A refusal cannot alter
    // either the existing journal or the next logical sequence number.
    reduce([...events, event], initialSeed);
    events.push(event);
    return event;
  };
  const snapshot = () => reduce(events, initialSeed);
  const current = id => checkpoint(snapshot().checkpoints, id);
  return {
    get events() { return Object.freeze([...events]); },
    append,
    snapshot,
    approve: (checkpointId, evidence = initialSeed.checkpoints.find(cp => cp.id === checkpointId)?.evidence) => {
      current(checkpointId);
      if (typeof evidence !== 'string' || !evidence.trim()) throw new Error('Acceptance evidence is required for human approval');
      append('checkpoint.approved', { checkpointId, approver: 'human-reviewer', acceptedEvidence: evidence.trim() });
    },
    createOrder: (checkpointId) => {
      const cp = current(checkpointId);
      append('paypal.order.created', { checkpointId, orderId: fixtureOrderId(checkpointId), amount: cp.amount, currency: initialSeed.currency, environment: 'sandbox' });
    },
    recordCaptureAttempt: (checkpointId) => {
      const cp = current(checkpointId);
      append('paypal.capture.requested', { checkpointId, orderId: cp.orderId, environment: 'sandbox' });
    },
    recordLostCaptureResponse: (checkpointId) => {
      const cp = current(checkpointId);
      append('paypal.capture.response_lost', { checkpointId, orderId: cp.orderId, outcome: 'unknown' });
    },
    recordWebhook: (checkpointId, eventId, captureId) => {
      const cp = current(checkpointId);
      const duplicate = events.some(e => e.type === 'paypal.webhook.received' && e.eventId === eventId);
      append('paypal.webhook.received', { checkpointId, eventId, captureId, duplicate, amount: cp.amount, currency: initialSeed.currency });
    },
    reconcile: (checkpointId, captureId) => {
      current(checkpointId);
      append('paypal.capture.reconciled', { checkpointId, captureId, outcome: 'captured', source: 'sandbox-transaction-lookup' });
    }
  };
}

export function reduce(events, seed = FIXTURE) {
  if (!Array.isArray(events)) throw new Error('Ledger events must be an array');
  const initialSeed = copySeed(seed);
  const checkpoints = Object.fromEntries(initialSeed.checkpoints.map(cp => [cp.id, { ...cp, approved: false, orderId: null, captureStatus: 'not_started', captureId: null, counted: 0 }]));
  const orders = new Map();
  const webhooks = new Map();
  const captures = new Map();
  const checkpointCaptures = new Map();
  const bindCapture = event => {
    requireId(event.captureId, 'Capture ID');
    if ((captures.has(event.captureId) && captures.get(event.captureId) !== event.checkpointId)
      || (checkpointCaptures.has(event.checkpointId) && checkpointCaptures.get(event.checkpointId) !== event.captureId)) {
      throw new Error('Capture identity conflict');
    }
    captures.set(event.captureId, event.checkpointId);
    checkpointCaptures.set(event.checkpointId, event.captureId);
  };
  for (const event of events) {
    validateEnvelope(event);
    const cp = checkpoint(checkpoints, event.checkpointId);
    switch (event.type) {
      case 'checkpoint.approved':
        if (cp.approved) throw new Error('Checkpoint already approved');
        if (event.approver !== 'human-reviewer') throw new Error('Explicit fixture human approval required');
        if (typeof event.acceptedEvidence !== 'string' || !event.acceptedEvidence.trim()) throw new Error('Acceptance evidence is required for human approval');
        cp.approved = true;
        break;
      case 'paypal.order.created':
        if (!cp.approved) throw new Error('Human approval required before order creation');
        if (cp.orderId) throw new Error('Order already exists');
        requireId(event.orderId, 'Order ID');
        if (orders.has(event.orderId)) throw new Error('Order identity conflict');
        requireAmount(event, cp, initialSeed.currency);
        if (event.environment !== 'sandbox') throw new Error('Only the sandbox fixture environment is supported');
        orders.set(event.orderId, event.checkpointId);
        cp.orderId = event.orderId;
        cp.captureStatus = 'ready';
        break;
      case 'paypal.capture.requested':
        if (!cp.orderId) throw new Error('Approved PayPal order required before capture');
        if (cp.captureStatus === 'pending') throw new Error('Capture is already pending; do not retry before its outcome is recorded');
        if (cp.captureStatus === 'unknown') throw new Error('Capture is not safe to retry; reconcile first');
        if (cp.captureStatus === 'captured') throw new Error('Capture already completed; do not retry');
        requireOrder(event, cp);
        if (event.environment !== 'sandbox') throw new Error('Only the sandbox fixture environment is supported');
        cp.captureStatus = 'pending';
        cp.captureRequested = true;
        break;
      case 'paypal.capture.response_lost':
        if (cp.captureStatus !== 'pending') throw new Error('Only a pending capture can lose its response');
        requireOrder(event, cp);
        if (event.outcome !== 'unknown') throw new Error('A lost capture response has an unknown outcome');
        cp.captureStatus = 'unknown';
        break;
      case 'paypal.webhook.received': {
        if (!cp.orderId) throw new Error('Order required before webhook');
        requireId(event.eventId, 'Webhook event ID');
        requireId(event.captureId, 'Capture ID');
        const prior = webhooks.get(event.eventId);
        if (prior && (prior.checkpointId !== event.checkpointId || prior.captureId !== event.captureId
          || prior.amount !== event.amount || prior.currency !== event.currency)) throw new Error('Webhook event identity conflict');
        requireAmount(event, cp, initialSeed.currency);
        if (event.duplicate !== Boolean(prior)) throw new Error('Webhook duplicate marker conflicts with event history');
        bindCapture(event);
        webhooks.set(event.eventId, event);
        // Receipt identity is retained during an unknown outcome, but receiving
        // a webhook does not replace the fixture's explicit reconciliation.
        if (!prior && cp.captureStatus !== 'captured' && cp.captureStatus !== 'unknown') {
          cp.captureStatus = 'captured'; cp.captureId = event.captureId; cp.counted = cp.amount;
        }
        break;
      }
      case 'paypal.capture.reconciled':
        if (cp.captureStatus !== 'unknown') throw new Error('Only an unknown capture can be reconciled');
        if (event.outcome !== 'captured' || event.source !== 'sandbox-transaction-lookup') throw new Error('Sandbox lookup evidence required for reconciliation');
        bindCapture(event);
        cp.captureStatus = 'captured'; cp.captureId = event.captureId; cp.counted = cp.amount;
        break;
    }
  }
  const total = initialSeed.checkpoints.reduce((sum, cp) => sum + cp.amount, 0);
  const approved = Object.values(checkpoints).filter(cp => cp.approved).length;
  const captured = Object.values(checkpoints).reduce((sum, cp) => sum + cp.counted, 0);
  return { checkpoints, total, approved, captured, remaining: total - captured };
}

export function replayFixture() {
  const ledger = createLedger();
  // Gate all payment action on explicit human acceptance; the first checkpoint
  // demonstrates a lost response, duplicated webhook, then read-only reconcile.
  ledger.approve('journey');
  ledger.createOrder('journey');
  ledger.recordCaptureAttempt('journey');
  ledger.recordLostCaptureResponse('journey');
  ledger.recordWebhook('journey', 'WH-EVT-FIXTURE-001', 'CAP-FIXTURE-001');
  ledger.recordWebhook('journey', 'WH-EVT-FIXTURE-001', 'CAP-FIXTURE-001');
  ledger.reconcile('journey', 'CAP-FIXTURE-001');
  return ledger;
}

import { FIXTURE, createLedger } from './ledger.mjs';

export const MAX_CHECKPOINTS = 12;
const wholeDollars = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });

export function formatUSD(cents) {
  if (!Number.isSafeInteger(cents)) throw new Error('USD display requires safe integer cents.');
  const magnitude = Math.abs(cents);
  // Dividing a large safe cent integer into a floating dollar value can change
  // its cents. Group the whole-dollar integer and append the exact remainder.
  return `${cents < 0 ? '-' : ''}$${wholeDollars.format(Math.floor(magnitude / 100))}.${String(magnitude % 100).padStart(2, '0')}`;
}

export function dollars(cents) {
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

export function parseDollars(value) {
  if (typeof value !== 'string' || !/^\d+(?:\.\d{1,2})?$/.test(value.trim())) return null;
  const [whole, fraction = ''] = value.trim().split('.');
  const cents = Number(whole) * 100 + Number(fraction.padEnd(2, '0'));
  return Number.isSafeInteger(cents) && cents > 0 ? cents : null;
}

export function draftFromFixture() {
  return {
    label: FIXTURE.label,
    brief: FIXTURE.brief,
    cap: dollars(FIXTURE.amount),
    checkpoints: FIXTURE.checkpoints.map(cp => ({
      title: cp.title, amount: dollars(cp.amount), evidence: cp.evidence
    }))
  };
}

export function draftBudget(draft) {
  const cap = parseDollars(draft.cap);
  const amounts = Array.from(draft.checkpoints, cp => parseDollars(cp?.amount));
  const sum = amounts.reduce((total, amount) => total + (amount ?? 0), 0);
  const allocated = amounts.includes(null) || !Number.isSafeInteger(sum) ? null : sum;
  return { cap, allocated, unallocated: cap === null || allocated === null ? null : cap - allocated };
}

export function validateScopeDraft(draft) {
  const errors = [];
  const text = (value, field, label, max) => {
    if (typeof value !== 'string' || !value.trim()) {
      errors.push({ field, message: `${label} is required.` });
      return '';
    }
    if (value.length > max) errors.push({ field, message: `${label} must be ${max} characters or fewer.` });
    return value.trim();
  };
  const label = text(draft?.label, 'label', 'Project name', 120);
  const brief = text(draft?.brief, 'brief', 'Creative brief', 8000);
  const cap = parseDollars(draft?.cap);
  if (cap === null) errors.push({ field: 'cap', message: 'Enter a positive project cap in USD with no more than two decimal places.' });
  const rows = Array.isArray(draft?.checkpoints) ? draft.checkpoints : [];
  if (rows.length < 1 || rows.length > MAX_CHECKPOINTS) {
    errors.push({ field: 'checkpoints', message: `Use between 1 and ${MAX_CHECKPOINTS} checkpoints.` });
  }
  const checkpoints = Array.from(rows.slice(0, MAX_CHECKPOINTS), (cp, index) => {
    const prefix = `checkpoints.${index}`;
    const title = text(cp?.title, `${prefix}.title`, `Checkpoint ${index + 1} title`, 160);
    const evidence = text(cp?.evidence, `${prefix}.evidence`, `Checkpoint ${index + 1} acceptance evidence`, 5000);
    const amount = parseDollars(cp?.amount);
    if (amount === null) errors.push({ field: `${prefix}.amount`, message: `Enter a positive USD amount for checkpoint ${index + 1}, with no more than two decimal places.` });
    // Identifiers belong to this draft, never to user-entered titles or receipts.
    return { id: `scope-${index + 1}`, title, amount, evidence };
  });
  const allocated = checkpoints.reduce((sum, cp) => sum + (cp.amount ?? 0), 0);
  if (!Number.isSafeInteger(allocated)) errors.push({ field: 'cap', message: 'The checkpoint total is too large.' });
  else if (cap !== null && allocated > cap) errors.push({ field: 'cap', message: 'Checkpoint amounts exceed the project cap. Increase the cap or reduce a checkpoint amount.' });
  if (errors.length) return { ok: false, errors, seed: null };
  const seed = {
    id: 'authored-scope-fixture', label, brief, currency: 'USD', amount: cap,
    buyer: 'Fictional fixture reviewer', seller: 'Fictional fixture creator', checkpoints
  };
  return { ok: true, errors: [], seed };
}

function availableActions(cp, events) {
  if (!cp.approved) return ['approve'];
  const receipts = events.filter(e => e.checkpointId === cp.id && e.type === 'paypal.webhook.received');
  switch (cp.captureStatus) {
    case 'not_started': return ['order'];
    case 'ready': return ['request'];
    case 'pending': return ['receipt', 'lose'];
    case 'unknown': return [...(receipts.length === 0 ? ['receipt'] : receipts.length === 1 ? ['duplicate'] : []), 'reconcile'];
    case 'captured': return receipts.length === 1 ? ['duplicate'] : [];
    default: return [];
  }
}

// A local fixture session, built on the product's ledger. It exposes only the
// explicit next-step controls used by the authoring page, never an append API.
export function createScopeReview(draft) {
  const validation = validateScopeDraft(draft);
  if (!validation.ok) throw new Error(validation.errors.map(error => error.message).join(' '));
  const seed = structuredClone(validation.seed);
  const ledger = createLedger(seed);
  const snapshot = () => {
    const events = structuredClone(ledger.events);
    const state = ledger.snapshot();
    return {
      plan: structuredClone(seed), ...state, events,
      unallocated: seed.amount - state.total,
      checkpoints: seed.checkpoints.map(cp => ({
        ...state.checkpoints[cp.id],
        acceptedEvidence: events.find(e => e.type === 'checkpoint.approved' && e.checkpointId === cp.id)?.acceptedEvidence ?? null,
        actions: availableActions(state.checkpoints[cp.id], events)
      }))
    };
  };
  const act = (checkpointId, action, evidence) => {
    const current = snapshot().checkpoints.find(cp => cp.id === checkpointId);
    if (!current) throw new Error('Unknown checkpoint.');
    if (!current.actions.includes(action)) throw new Error('That action is not available in the current checkpoint state.');
    const captureId = `CAP-${checkpointId.toUpperCase()}`;
    const eventId = `WH-${checkpointId.toUpperCase()}`;
    switch (action) {
      case 'approve':
        if (typeof evidence !== 'string' || evidence.length > 5000) throw new Error('Acceptance evidence must be 5000 characters or fewer.');
        ledger.approve(checkpointId, evidence);
        break;
      case 'order': ledger.createOrder(checkpointId); break;
      case 'request': ledger.recordCaptureAttempt(checkpointId); break;
      case 'lose': ledger.recordLostCaptureResponse(checkpointId); break;
      case 'receipt':
      case 'duplicate': ledger.recordWebhook(checkpointId, eventId, captureId); break;
      case 'reconcile': ledger.reconcile(checkpointId, captureId); break;
    }
    return snapshot();
  };
  return Object.freeze({ snapshot, act });
}

import { MAX_CHECKPOINTS, createScopeReview } from './scope-plan.mjs';

export const WORKSPACE_SCHEMA = 'scopesignal.scope-workspace';
export const WORKSPACE_VERSION = 1;
export const WORKSPACE_FILENAME = 'scopesignal-workspace-v1.json';
export const MAX_WORKSPACE_BYTES = 1024 * 1024;
export const MAX_WORKSPACE_EVENTS = 96;

function exactObject(value, fields, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)
    || Object.keys(value).length !== fields.length
    || fields.some(field => !Object.hasOwn(value, field))) {
    throw new Error(label + ' has missing, extra, or unsupported fields.');
  }
}

function text(value, maximum, label, multiline = false) {
  if (typeof value !== 'string' || value.length > maximum) {
    throw new Error(label + ' must be text of at most ' + maximum + ' characters.');
  }
  // Native textareas use LF; text inputs strip line breaks on assignment.
  // Admit only values the editor can preserve rather than rewriting a file.
  if (value.includes('\r') || (!multiline && value.includes('\n'))) {
    throw new Error(label + (multiline
      ? ' must use LF line breaks, as saved by this workspace.'
      : ' must stay on one line.'));
  }
  return value;
}

// Draft admission deliberately allows unfinished fields. Ordinary review
// validation still decides whether the restored draft can become a plan.
function copyDraft(value) {
  exactObject(value, ['label', 'brief', 'cap', 'checkpoints'], 'Saved draft');
  if (!Array.isArray(value.checkpoints) || value.checkpoints.length < 1
    || value.checkpoints.length > MAX_CHECKPOINTS) {
    throw new Error('A saved draft must contain 1–12 checkpoints.');
  }
  return {
    label: text(value.label, 120, 'Project name'),
    brief: text(value.brief, 8000, 'Creative brief', true),
    cap: text(value.cap, 64, 'Project cap'),
    checkpoints: Array.from(value.checkpoints, (row, index) => {
      const label = 'Checkpoint ' + (index + 1);
      exactObject(row, ['title', 'amount', 'evidence'], label);
      return {
        title: text(row.title, 160, label + ' deliverable'),
        amount: text(row.amount, 64, label + ' amount'),
        evidence: text(row.evidence, 5000, label + ' planned evidence', true)
      };
    })
  };
}

const actions = Object.freeze({
  'checkpoint.approved': 'approve',
  'paypal.order.created': 'order',
  'paypal.capture.requested': 'request',
  'paypal.capture.response_lost': 'lose',
  'paypal.capture.reconciled': 'reconcile'
});

function sameEvent(saved, generated) {
  const fields = Object.keys(generated);
  return saved && typeof saved === 'object' && !Array.isArray(saved)
    && Object.keys(saved).length === fields.length
    && fields.every(field => Object.hasOwn(saved, field)
      && Object.is(saved[field], generated[field]));
}

function restoreReview(draft, events) {
  const review = createScopeReview(draft);
  for (const [index, event] of events.entries()) {
    let action;
    if (event && typeof event === 'object' && !Array.isArray(event)) {
      action = Object.hasOwn(actions, event.type) ? actions[event.type] : undefined;
      if (event.type === 'paypal.webhook.received') {
        action = event.duplicate === true ? 'duplicate' : 'receipt';
      }
    }
    if (!action) throw new Error('Saved event ' + (index + 1) + ' is unsupported.');
    // Replay only the existing explicit authoring controls into a private
    // fixture. The current workspace is never involved in file admission.
    const state = review.act(event.checkpointId, action, event.acceptedEvidence);
    if (!sameEvent(event, state.events.at(-1))) {
      throw new Error('Saved event ' + (index + 1) + ' does not match its fixture history.');
    }
  }
  return review;
}

export function decodeScopeWorkspace(contents) {
  if (typeof contents !== 'string' || contents.length > MAX_WORKSPACE_BYTES
    || new TextEncoder().encode(contents).byteLength > MAX_WORKSPACE_BYTES) {
    throw new Error('Choose a UTF-8 workspace JSON file no larger than 1 MiB.');
  }
  let record;
  try { record = JSON.parse(contents); }
  catch { throw new Error('The selected file is not valid workspace JSON.'); }
  exactObject(record, ['schema', 'version', 'fixtureOnly', 'paymentEvidence',
    'stage', 'draft', 'events', 'evidenceDrafts'], 'Workspace file');
  if (record.schema !== WORKSPACE_SCHEMA || record.version !== WORKSPACE_VERSION
    || record.fixtureOnly !== true || record.paymentEvidence !== false
    || !['draft', 'review'].includes(record.stage)) {
    throw new Error('This file is not a supported version 1 fictional workspace.');
  }
  const draft = copyDraft(record.draft);
  if (!Array.isArray(record.events) || record.events.length > MAX_WORKSPACE_EVENTS) {
    throw new Error('The saved fixture history is missing or too large.');
  }
  if (!Array.isArray(record.evidenceDrafts) || record.evidenceDrafts.length > MAX_CHECKPOINTS) {
    throw new Error('The saved evidence drafts are missing or too large.');
  }
  if (record.stage === 'draft' && (record.events.length || record.evidenceDrafts.length)) {
    throw new Error('An editable draft cannot contain approval events or review evidence.');
  }
  const review = record.stage === 'review' ? restoreReview(draft, record.events) : null;
  const state = review?.snapshot();
  const evidenceDrafts = new Map();
  for (const entry of record.evidenceDrafts) {
    exactObject(entry, ['checkpointId', 'text'], 'Saved evidence draft');
    const checkpoint = state?.checkpoints.find(cp => cp.id === entry.checkpointId);
    if (!checkpoint || checkpoint.approved || evidenceDrafts.has(entry.checkpointId)) {
      throw new Error('Saved evidence must belong to a distinct unapproved checkpoint.');
    }
    evidenceDrafts.set(entry.checkpointId, text(entry.text, 5000, 'Pending evidence', true));
  }
  return {
    draft, review, evidenceDrafts,
    summary: {
      label: state?.plan.label ?? draft.label,
      stage: record.stage,
      checkpoints: draft.checkpoints.length,
      approved: state?.approved ?? 0,
      events: record.events.length
    }
  };
}

export function encodeScopeWorkspace({ draft, review = null, evidenceDrafts = new Map() }) {
  const snapshot = review?.snapshot();
  if (!(evidenceDrafts instanceof Map)) throw new Error('Evidence drafts are unavailable.');
  const pending = [];
  if (snapshot) {
    for (const [checkpointId, value] of evidenceDrafts) {
      const checkpoint = snapshot.checkpoints.find(cp => cp.id === checkpointId);
      if (!checkpoint) throw new Error('An evidence draft has an unknown checkpoint.');
      // An approval's accepted text comes only from its recorded event. A
      // formerly pending editor value must never replace that accepted text.
      if (!checkpoint.approved) pending.push({ checkpointId, text: value });
    }
  }
  const record = {
    schema: WORKSPACE_SCHEMA, version: WORKSPACE_VERSION,
    fixtureOnly: true, paymentEvidence: false,
    stage: snapshot ? 'review' : 'draft',
    draft: copyDraft(draft),
    events: snapshot ? structuredClone(snapshot.events) : [],
    evidenceDrafts: pending
  };
  const contents = JSON.stringify(record, null, 2) + '\n';
  const restored = decodeScopeWorkspace(contents);
  if (snapshot && JSON.stringify(restored.review.snapshot()) !== JSON.stringify(snapshot)) {
    throw new Error('The workspace plan and recorded review do not match.');
  }
  return contents;
}

